(() => { const input=document.getElementById('phone'); if(!input || !window.intlTelInput)return; const lib=window.intlTelInput; const instance=lib(input,{initialCountry:'br',countryOrder:['br','us','gb','pt','fr','es'],countrySelectorMode:lib.COUNTRY_SELECTOR_MODE.DROPDOWN,dropdownParent:document.body,matchDropdownWidth:true,separateDialCode:false,numberDisplayFormat:lib.NUMBER_FORMAT.NATIONAL,placeholderNumberPolicy:lib.PLACEHOLDER_POLICY.AGGRESSIVE,customPlaceholder:(example,country)=>country?.iso2==='br'?'(11) 96123-4567':example,strictMode:true,formatAsYouType:true}); window.PhoneField={getNumber:()=>instance.getNumber(),isValid:()=>instance.isValidNumber()===true,getCountry:()=>instance.getSelectedCountry()?.iso2||''}; input.addEventListener('blur',()=>{const valid=instance.isValidNumber()===true;input.setAttribute('aria-invalid',String(!valid));document.getElementById('phone-error').textContent=valid?'':'Confira o número e o DDD/código do país.';}); })();